// Exploiting Spatial Locality: Row-Major Traversal
// C/C++ stores 2D arrays row-by-row (contiguous memory).
#define N 512
int matrix[N][N];

void process_spatial_good() {
    // Inner loop iterates through contiguous memory (j)
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            matrix[i][j] += 1; // High cache hit rate
        }
    }
}

// Violating Spatial Locality: Column-Major Traversal
void process_spatial_bad() {
    // Inner loop forces a large stride jump (N * sizeof(int))
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N; ++i) {
            matrix[i][j] += 1; // High cache miss rate
        }
    }
}
